window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f0f5b6b14a1401f8"]={"versions": [{"id": "FIG-f0f5b6b14a1401f8", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Tabellarische Schnittstellenspezifikation / Port-Interface-Matrix (Data Dictionary) für AUTOSAR Application Interfaces (AI) gemäß <code>AUTOSAR_CP_EXP_AIADASAndVMC</code>.\n</li><li><strong>Architektonische Einordnung:</strong> Spezifikation der normierten Signal- und Datenelemente an den VFB-Schnittstellen (Virtual Function Bus) zwischen den ADAS-Planungsfunktionen (<strong>ACC</strong>, <strong>AEB</strong>, <strong>LKA</strong>) und der zentralen Bewegungsregelung/-koordination (<strong>AMG</strong> – Actuator Motion Gateway / Motion Coordinator):\n<ul class=\"fig-list\"><li><strong>PLN1 (Planning 1):</strong> Steuerungs- und Anforderungspfad (<em>Feedforward/Command Interface</em>) von den Planungs-SWCs zu AMG.\n</li><li><strong>PLN2 (1) (Planning 2, Teil 1):</strong> Rückmelde-, Übersteuerungs- und Zustandspfad (<em>Feedback &amp; Coordination Interface</em>) von AMG zurück an die Planungs-SWCs.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Beteiligte Software-Komponenten (SWCs) / Akteure</h5>\n<ul class=\"fig-list\"><li><strong>Planungs-SWCs (Output Source in PLN1 / Output Dest. in PLN2):</strong>\n<ul class=\"fig-list\"><li><code>ACC</code> (Adaptive Cruise Control): Längsführungskomponente für Komfort/Abstand.\n</li><li><code>AEB</code> (Autonomous Emergency Braking): Sicherheitskritische Notbremskomponente.\n</li><li><code>LKA</code> (Lane Keeping Assist): Querführungskomponente.\n</li></ul>\n</li><li><strong>Koordinations-SWC:</strong>\n<ul class=\"fig-list\"><li><code>AMG</code> (Actuator Motion Gateway): Schlichtungs- und Vermittlungsinstanz zur Ansteuerung der Subsysteme (Powertrain <code>PT</code>, Braking <code>BRK</code>, Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Stereotypen &amp; Port-Interface-Modellierung (AUTOSAR M1/M2)</h5>\n<ul class=\"fig-list\"><li>Die Datenübertragung erfolgt über <code>SenderReceiverInterface</code> (Stereotyp «isOfType» über P-Ports und R-Ports):\n<ul class=\"fig-list\"><li>P-Port an Planungs-SWCs, R-Port an AMG für PLN1.\n</li><li>P-Port an AMG, R-Port an Planungs-SWCs für PLN2(1).\n</li></ul>\n</li><li>Datenmodellierung: <code>VariableDataPrototype</code> mit Typisierung über <code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>, Skalierung über <code>CompuMethod</code> (Linear bzw. TextTable) und physikalische Maßeinheiten (<code>Unit</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Signaldefinitionen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Gruppe</th><th>Set-ID</th><th>Datenelement (VariableDataPrototype)</th><th>Quelle → Ziel</th><th>Physik. Einheit</th><th>Datentyp / Wertebereich (<code>CompuMethod</code>)</th><th>Init-Wert</th></tr></thead><tbody><tr><td><strong>PLN1</strong></td><td>PLN1-2</td><td><code>ACC target acceleration</code></td><td>ACC → AMG</td><td>m/s^2</td><td>Kontinuierlich (Längsbeschleunigung)</td><td>0</td></tr><tr><td></td><td></td><td><code>ACC target acceleration validity information</code></td><td>ACC → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>ACC status</code></td><td>ACC → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: STANDBY</code>, <code>2: ON</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>ACC standstill control request</code></td><td>ACC → AMG</td><td>–</td><td><code>0: Not requested</code>, <code>1: Requested</code></td><td>0</td></tr><tr><td></td><td>PLN1-6</td><td><code>AEB target acceleration</code></td><td>AEB → AMG</td><td>m/s^2</td><td>Kontinuierlich (Sollverzögerung/-beschleunigung)</td><td>0</td></tr><tr><td></td><td></td><td><code>AEB target acceleration validity information</code></td><td>AEB → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>AEB status</code></td><td>AEB → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: -</code>, <code>2: ON (Standby)</code>, <code>3: Warning</code>, <code>4: Decel prep (+ Warn)</code>, <code>5: Soft decel (+ Warn)</code>, <code>6: Strong decel (+ Warn)</code>, <code>7: Vehicle stop hold</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>AEB standstill control request</code></td><td>AEB → AMG</td><td>–</td><td><code>0: Not requested</code>, <code>1: Requested</code></td><td>0</td></tr><tr><td></td><td>PLN1-10</td><td><code>LKA target curvature</code></td><td>LKA → AMG</td><td>1/m</td><td>Kontinuierlich (Krümmungsanforderung $\\kappa$)</td><td>0</td></tr><tr><td></td><td></td><td><code>LKA target curvature validity information</code></td><td>LKA → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>LKA status</code></td><td>LKA → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: STANDBY</code>, <code>2: ON</code></td><td>0</td></tr><tr><td><strong>PLN2(1)</strong></td><td>–</td><td><code>Driver operation (Drive)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Fahrpedal-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver operation (Braking)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Bremspedal-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver operation (Steering)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Lenkrad-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver requested acceleration</code></td><td>AMG → ACC, AEB</td><td>m/s^2</td><td>Positiver Wert (Gaspedal-Fahrerwunsch)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver request braking acceleration</code></td><td>AMG → AEB</td><td>m/s^2</td><td>Negativer Wert (Bremspedal-Fahrerwunsch)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Powertrain acceleration capability upper limit</code></td><td>AMG → ACC</td><td>m/s^2</td><td>Dynamische Obergrenze innerhalb Zeitfenster $\\Delta t$ (** ms)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Powertrain acceleration capability lower limit</code></td><td>AMG → ACC</td><td>m/s^2</td><td>Dynamische Untergrenze innerhalb Zeitfenster $\\Delta t$ (** ms)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>PT system reliability information</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Initializing</code>, <code>1: Calibrating</code>, <code>2: Normal</code>, <code>3: Under protection control</code>, <code>4: Invalid</code>, <code>5: Failure (confirmed)</code>, <code>6-F: Spare</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>BRK system reliability information</code></td><td>AMG → ACC, AEB</td><td>–</td><td>Identisch zum PT-Zuverlässigkeitsstatus (Init, Calib, Normal, Protect, Invalid, Fail)</td><td>0</td></tr></tbody></table></div>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmodell &amp; Kopplung</h5>\n<ul class=\"fig-list\"><li><strong>Asynchrone zyklische Übertragung:</strong> Sender-Receiver-Kommunikation über periodische RTE-Tasks (typische Zykluszeiten: 10 ms bis 20 ms für Längs-/Querregelung).\n</li><li><strong>Signalbündelung &amp; Konsistenz (Set-IDs):</strong>\n<ul class=\"fig-list\"><li>Anforderungen sind zwingend an Status-/Validitätssignale gekoppelt (<code>PLN1-2</code>, <code>PLN1-6</code>, <code>PLN1-10</code>). \n</li><li>Die Auswertung im AMG darf die Sollwerte (<code>target acceleration</code>, <code>target curvature</code>) nur verarbeiten, wenn das zugehörige Gültigkeitssignal (<code>validity information == 1 (Valid)</code>) gesetzt ist.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Arbitrierungs- und Override-Kaskade (AMG)</h5>\n<ol class=\"fig-list\"><li><strong>Fahrerübersteuerung (PLN2):</strong> Signale <code>Driver operation (Drive/Braking/Steering)</code> melden Eingriffe (<code>2: Operate</code>). AMG priorisiert den Fahrerwunsch (<code>Driver requested acceleration</code>) und erzwingt den Übergang der ADAS-Funktionen von <code>ON</code> nach <code>STANDBY</code> oder <code>OFF</code>.\n</li><li><strong>Begrenzung auf Systemgrenzen:</strong> <code>Powertrain acceleration capability upper/lower limit</code> begrenzt die Sollwerttrajektorie von ACC dynamisch auf das physikalisch und thermisch innerhalb von <code>** ms</code> Stellzeit Machbare.\n</li><li><strong>Fehler- und Degradationspfade:</strong>\n<ul class=\"fig-list\"><li>Meldet <code>PT system reliability information</code> oder <code>BRK system reliability information</code> einen Zustand ≥ 3 (<code>Protection control</code>, <code>Invalid</code>, <code>Failure</code>), müssen ACC und LKA degradieren/abschalten (<code>STANDBY</code>/<code>OFF</code>).\n</li><li>AEB nutzt die Zustände 3–7 (<code>Warning</code> bis <code>Vehicle stop hold</code>) in einer deterministischen Eskalationskette; bei Bestätigung des Fahrzeugstillstands schaltet <code>AEB standstill control request</code> auf 1 um.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<h5 class=\"fig-section-h5\">RTE- und Schnittstellen-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong>Data Consistency:</strong> Für die Sets <code>PLN1-2</code>, <code>PLN1-6</code> und <code>PLN1-10</code> ist RTE-seitig konsistenter Datenzugriff (<code>implicit read/write</code> oder Record-Grouping) zu konfigurieren, um Tearing zwischen physikalischem Sollwert und Gültigkeitsflag zu verhindern.\n</li><li><strong>Initialisierung &amp; Timeout:</strong>\n<ul class=\"fig-list\"><li>Alle Signale besitzen den Defaultwert <code>0</code> (<code>Invalid</code>, <code>OFF</code>, <code>Indefinite</code>, <code>Initializing</code>).\n</li><li>Im E2E-Stack (End-to-End Protection Profile) bzw. Com-Monitoring führt ein Signal-Timeout (<code>ComTimeoutNotification</code>) dazu, dass die Gültigkeit auf <code>0 (Invalid)</code> abfällt und der Status auf <code>OFF</code> gesetzt wird.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Applikationslogik &amp; Validierungsverträge</h5>\n<ul class=\"fig-list\"><li><strong>Keine implizite Gültigkeit:</strong> Ein Wert ungleich Null in <code>target acceleration</code> ist ohne gesetztes Validitätsbit zwingend zu verwerfen.\n</li><li><strong>Vorzeichenkonvention:</strong>\n<ul class=\"fig-list\"><li><code>Driver requested acceleration</code>: Strikt positiv (≥ 0\\,m/s^2).\n</li><li><code>Driver request braking acceleration</code>: Strikt negativ (≤ 0\\,m/s^2).\n</li></ul>\n</li><li><strong>Reliability-Zustandsautomat:</strong> Die Status-Enums für PT und BRK (<code>0..5</code>) dürfen nicht isoliert interpretiert werden, sondern müssen direkt an die systemweite ADAS-Zustandsmaschine (State Management) gekoppelt werden (normativer Hinweis: <em>„Handled as a set with the state transition diagram“</em>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4a4d01fe6a17d41f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Tabellarische Schnittstellenspezifikation / Port-Interface-Matrix (Data Dictionary) für AUTOSAR Application Interfaces (AI) gemäß <code>AUTOSAR_CP_EXP_AIADASAndVMC</code>.\n</li><li><strong>Architektonische Einordnung:</strong> Spezifikation der normierten Signal- und Datenelemente an den VFB-Schnittstellen (Virtual Function Bus) zwischen den ADAS-Planungsfunktionen (<strong>ACC</strong>, <strong>AEB</strong>, <strong>LKA</strong>) und der zentralen Bewegungsregelung/-koordination (<strong>AMG</strong> – Actuator Motion Gateway / Motion Coordinator):\n<ul class=\"fig-list\"><li><strong>PLN1 (Planning 1):</strong> Steuerungs- und Anforderungspfad (<em>Feedforward/Command Interface</em>) von den Planungs-SWCs zu AMG.\n</li><li><strong>PLN2 (1) (Planning 2, Teil 1):</strong> Rückmelde-, Übersteuerungs- und Zustandspfad (<em>Feedback &amp; Coordination Interface</em>) von AMG zurück an die Planungs-SWCs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Beteiligte Software-Komponenten (SWCs) / Akteure</h5>\n<ul class=\"fig-list\"><li><strong>Planungs-SWCs (Output Source in PLN1 / Output Dest. in PLN2):</strong>\n<ul class=\"fig-list\"><li><code>ACC</code> (Adaptive Cruise Control): Längsführungskomponente für Komfort/Abstand.\n</li><li><code>AEB</code> (Autonomous Emergency Braking): Sicherheitskritische Notbremskomponente.\n</li><li><code>LKA</code> (Lane Keeping Assist): Querführungskomponente.\n</li></ul>\n</li><li><strong>Koordinations-SWC:</strong>\n<ul class=\"fig-list\"><li><code>AMG</code> (Actuator Motion Gateway): Schlichtungs- und Vermittlungsinstanz zur Ansteuerung der Subsysteme (Powertrain <code>PT</code>, Braking <code>BRK</code>, Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Stereotypen &amp; Port-Interface-Modellierung (AUTOSAR M1/M2)</h5>\n<ul class=\"fig-list\"><li>Die Datenübertragung erfolgt über <code>SenderReceiverInterface</code> (Stereotyp «isOfType» über P-Ports und R-Ports):\n<ul class=\"fig-list\"><li>P-Port an Planungs-SWCs, R-Port an AMG für PLN1.\n</li><li>P-Port an AMG, R-Port an Planungs-SWCs für PLN2(1).\n</li></ul>\n</li><li>Datenmodellierung: <code>VariableDataPrototype</code> mit Typisierung über <code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>, Skalierung über <code>CompuMethod</code> (Linear bzw. TextTable) und physikalische Maßeinheiten (<code>Unit</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Signaldefinitionen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Gruppe</th><th>Set-ID</th><th>Datenelement (VariableDataPrototype)</th><th>Quelle → Ziel</th><th>Physik. Einheit</th><th>Datentyp / Wertebereich (<code>CompuMethod</code>)</th><th>Init-Wert</th></tr></thead><tbody><tr><td><strong>PLN1</strong></td><td>PLN1-2</td><td><code>ACC target acceleration</code></td><td>ACC → AMG</td><td>m/s^2</td><td>Kontinuierlich (Längsbeschleunigung)</td><td>0</td></tr><tr><td></td><td></td><td><code>ACC target acceleration validity information</code></td><td>ACC → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>ACC status</code></td><td>ACC → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: STANDBY</code>, <code>2: ON</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>ACC standstill control request</code></td><td>ACC → AMG</td><td>–</td><td><code>0: Not requested</code>, <code>1: Requested</code></td><td>0</td></tr><tr><td></td><td>PLN1-6</td><td><code>AEB target acceleration</code></td><td>AEB → AMG</td><td>m/s^2</td><td>Kontinuierlich (Sollverzögerung/-beschleunigung)</td><td>0</td></tr><tr><td></td><td></td><td><code>AEB target acceleration validity information</code></td><td>AEB → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>AEB status</code></td><td>AEB → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: -</code>, <code>2: ON (Standby)</code>, <code>3: Warning</code>, <code>4: Decel prep (+ Warn)</code>, <code>5: Soft decel (+ Warn)</code>, <code>6: Strong decel (+ Warn)</code>, <code>7: Vehicle stop hold</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>AEB standstill control request</code></td><td>AEB → AMG</td><td>–</td><td><code>0: Not requested</code>, <code>1: Requested</code></td><td>0</td></tr><tr><td></td><td>PLN1-10</td><td><code>LKA target curvature</code></td><td>LKA → AMG</td><td>1/m</td><td>Kontinuierlich (Krümmungsanforderung $\\kappa$)</td><td>0</td></tr><tr><td></td><td></td><td><code>LKA target curvature validity information</code></td><td>LKA → AMG</td><td>–</td><td><code>0: Invalid</code>, <code>1: Valid</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>LKA status</code></td><td>LKA → AMG</td><td>–</td><td><code>0: OFF</code>, <code>1: STANDBY</code>, <code>2: ON</code></td><td>0</td></tr><tr><td><strong>PLN2(1)</strong></td><td>–</td><td><code>Driver operation (Drive)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Fahrpedal-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver operation (Braking)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Bremspedal-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver operation (Steering)</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Indefinite</code>, <code>1: Not operate</code>, <code>2: Operate</code> (Lenkrad-Override)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver requested acceleration</code></td><td>AMG → ACC, AEB</td><td>m/s^2</td><td>Positiver Wert (Gaspedal-Fahrerwunsch)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Driver request braking acceleration</code></td><td>AMG → AEB</td><td>m/s^2</td><td>Negativer Wert (Bremspedal-Fahrerwunsch)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Powertrain acceleration capability upper limit</code></td><td>AMG → ACC</td><td>m/s^2</td><td>Dynamische Obergrenze innerhalb Zeitfenster $\\Delta t$ (** ms)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>Powertrain acceleration capability lower limit</code></td><td>AMG → ACC</td><td>m/s^2</td><td>Dynamische Untergrenze innerhalb Zeitfenster $\\Delta t$ (** ms)</td><td>0</td></tr><tr><td></td><td>–</td><td><code>PT system reliability information</code></td><td>AMG → ACC, AEB, LKA</td><td>–</td><td><code>0: Initializing</code>, <code>1: Calibrating</code>, <code>2: Normal</code>, <code>3: Under protection control</code>, <code>4: Invalid</code>, <code>5: Failure (confirmed)</code>, <code>6-F: Spare</code></td><td>0</td></tr><tr><td></td><td>–</td><td><code>BRK system reliability information</code></td><td>AMG → ACC, AEB</td><td>–</td><td>Identisch zum PT-Zuverlässigkeitsstatus (Init, Calib, Normal, Protect, Invalid, Fail)</td><td>0</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmodell &amp; Kopplung</h5>\n<ul class=\"fig-list\"><li><strong>Asynchrone zyklische Übertragung:</strong> Sender-Receiver-Kommunikation über periodische RTE-Tasks (typische Zykluszeiten: 10 ms bis 20 ms für Längs-/Querregelung).\n</li><li><strong>Signalbündelung &amp; Konsistenz (Set-IDs):</strong>\n<ul class=\"fig-list\"><li>Anforderungen sind zwingend an Status-/Validitätssignale gekoppelt (<code>PLN1-2</code>, <code>PLN1-6</code>, <code>PLN1-10</code>). \n</li><li>Die Auswertung im AMG darf die Sollwerte (<code>target acceleration</code>, <code>target curvature</code>) nur verarbeiten, wenn das zugehörige Gültigkeitssignal (<code>validity information == 1 (Valid)</code>) gesetzt ist.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Arbitrierungs- und Override-Kaskade (AMG)</h5>\n<ol class=\"fig-list\"><li><strong>Fahrerübersteuerung (PLN2):</strong> Signale <code>Driver operation (Drive/Braking/Steering)</code> melden Eingriffe (<code>2: Operate</code>). AMG priorisiert den Fahrerwunsch (<code>Driver requested acceleration</code>) und erzwingt den Übergang der ADAS-Funktionen von <code>ON</code> nach <code>STANDBY</code> oder <code>OFF</code>.\n</li><li><strong>Begrenzung auf Systemgrenzen:</strong> <code>Powertrain acceleration capability upper/lower limit</code> begrenzt die Sollwerttrajektorie von ACC dynamisch auf das physikalisch und thermisch innerhalb von <code>** ms</code> Stellzeit Machbare.\n</li><li><strong>Fehler- und Degradationspfade:</strong>\n<ul class=\"fig-list\"><li>Meldet <code>PT system reliability information</code> oder <code>BRK system reliability information</code> einen Zustand ≥ 3 (<code>Protection control</code>, <code>Invalid</code>, <code>Failure</code>), müssen ACC und LKA degradieren/abschalten (<code>STANDBY</code>/<code>OFF</code>).\n</li><li>AEB nutzt die Zustände 3–7 (<code>Warning</code> bis <code>Vehicle stop hold</code>) in einer deterministischen Eskalationskette; bei Bestätigung des Fahrzeugstillstands schaltet <code>AEB standstill control request</code> auf 1 um.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<h5 class=\"fig-section-h5\">RTE- und Schnittstellen-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong>Data Consistency:</strong> Für die Sets <code>PLN1-2</code>, <code>PLN1-6</code> und <code>PLN1-10</code> ist RTE-seitig konsistenter Datenzugriff (<code>implicit read/write</code> oder Record-Grouping) zu konfigurieren, um Tearing zwischen physikalischem Sollwert und Gültigkeitsflag zu verhindern.\n</li><li><strong>Initialisierung &amp; Timeout:</strong>\n<ul class=\"fig-list\"><li>Alle Signale besitzen den Defaultwert <code>0</code> (<code>Invalid</code>, <code>OFF</code>, <code>Indefinite</code>, <code>Initializing</code>).\n</li><li>Im E2E-Stack (End-to-End Protection Profile) bzw. Com-Monitoring führt ein Signal-Timeout (<code>ComTimeoutNotification</code>) dazu, dass die Gültigkeit auf <code>0 (Invalid)</code> abfällt und der Status auf <code>OFF</code> gesetzt wird.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Applikationslogik &amp; Validierungsverträge</h5>\n<ul class=\"fig-list\"><li><strong>Keine implizite Gültigkeit:</strong> Ein Wert ungleich Null in <code>target acceleration</code> ist ohne gesetztes Validitätsbit zwingend zu verwerfen.\n</li><li><strong>Vorzeichenkonvention:</strong>\n<ul class=\"fig-list\"><li><code>Driver requested acceleration</code>: Strikt positiv (≥ 0\\,m/s^2).\n</li><li><code>Driver request braking acceleration</code>: Strikt negativ (≤ 0\\,m/s^2).\n</li></ul>\n</li><li><strong>Reliability-Zustandsautomat:</strong> Die Status-Enums für PT und BRK (<code>0..5</code>) dürfen nicht isoliert interpretiert werden, sondern müssen direkt an die systemweite ADAS-Zustandsmaschine (State Management) gekoppelt werden (normativer Hinweis: <em>„Handled as a set with the state transition diagram“</em>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f0f5b6b14a1401f8", "to": "FIG-4a4d01fe6a17d41f", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
